```
my-provider/
├── package.json
├── tsconfig.json
├── src/
│   ├── index.ts          # Entry point — register handlers with SDK
│   └── MyProvider.ts     # BaseProvider subclass — environment lifecycle
└── dist/
    └── index.js
```

